Top 8 tools for "search text content inside files in sandbox". Invoke one with call_tool: {"name": "<name>", "arguments": {...}}.

[
  {
    "description": "Search for code across GitHub repositories using GitHub's native code search engine. Best for finding exact symbols, function names, class definitions, or specific code patterns by keyword. Use get_file_contents to retrieve full file content after finding it.\n\nParameters:\n- fields: Fields to include in results\n- order: Sort order (\"asc\" or \"desc\")\n- page: Page number\n- perPage: Results per page\n- query: GitHub code search query string (supports qualifiers like repo:, language:, path:)\n- sort: Sort field",
    "inputSchema": {
      "properties": {
        "fields": {
          "description": "Subset of fields to return for each code search result. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'repository' and 'text_matches' in particular drops the largest per-result data.",
          "items": {
            "enum": [
              "name",
              "path",
              "sha",
              "repository",
              "text_matches"
            ],
            "type": "string"
          },
          "type": "array"
        },
        "order": {
          "description": "Sort order for results",
          "enum": [
            "asc",
            "desc"
          ],
          "type": "string"
        },
        "page": {
          "description": "Page number for pagination (min 1)",
          "minimum": 1,
          "type": "number"
        },
        "perPage": {
          "description": "Results per page for pagination (min 1, max 100)",
          "maximum": 100,
          "minimum": 1,
          "type": "number"
        },
        "query": {
          "description": "Search query (GitHub code search REST). Implicit AND between terms; supports `OR`, `NOT`, and `\"quoted phrase\"` for exact match. Qualifiers: `repo:owner/repo`, `org:`, `user:`, `language:`, `path:dir` (prefix match), `filename:exact.ext`, `extension:`, `in:file`, `in:path`, `size:`, `is:archived`, `is:fork`. Max 256 chars. Examples: `WithContext language:go org:github`; `\"package main\" repo:o/r`; `func extension:go path:cmd repo:o/r`; `NOT TODO language:go repo:o/r`.",
          "type": "string"
        },
        "sort": {
          "description": "Sort field ('indexed' only)",
          "type": "string"
        }
      },
      "required": [
        "query"
      ],
      "type": "object"
    },
    "name": "github:search_code"
  },
  {
    "description": "Recursively search for files and directories whose paths match a glob-style pattern, returning full paths of all matches. Use *.ext to match in the current directory only, or **/*.ext to match across all subdirectories. Only searches within allowed directories.\n\nParameters:\n- path: Root directory to search within (must be within allowed directories)\n- pattern: Glob-style pattern matched against relative paths (e.g., \"**/*.json\")\n- excludePatterns: Array of glob-style patterns for paths to exclude from results",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "properties": {
        "excludePatterns": {
          "default": [],
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "path": {
          "type": "string"
        },
        "pattern": {
          "type": "string"
        }
      },
      "required": [
        "path",
        "pattern"
      ],
      "type": "object"
    },
    "name": "fs:search_files"
  },
  {
    "description": "Execute one or more Hugging Face Hub filesystem operations in a single call and return their results. Supports browsing, reading, and searching files, repos, collections, papers, and docs on the Hub.\n\nUse instead of hub_repo_search/hub_repo_details when you need low-level filesystem access, raw file contents, recursive file matching, trending listings, paper/doc search, or image attachment.\n\nOperations are submitted as an array of {cmd, args} objects. Each args array is a list of strings matching the grammar below.\n\nCommands:\n- search  — discover repos, spaces, collections, papers, or docs by query or tag; use for open-ended discovery\n- ls      — list contents of a known directory or scope (e.g. hf://models/trending)\n- find    — recursively match files/dirs within a known scope using globs\n- stat    — get filesystem metadata for a URI when the target type is uncertain; does NOT read file contents\n- cat     — read a text file's contents by exact URI; use directly without a preceding ls or stat\n- attach  — fetch a complete JPEG, PNG, or WebP image by URI\n\nParameters (each operation):\n- cmd: one of ls | cat | attach | stat | find | search\n- args: array of strings forming the command line, e.g. [\"hf://models/org/repo\", \"--recursive\"]\n\nURI schemes: hf://models, hf://datasets, hf://spaces, hf://collections, hf://papers, hf://docs\nSearch scopes: hf://models|datasets|spaces[/OWNER], hf://collections[/OWNER], hf://papers, hf://docs[/...]\nSORT values: createdAt | downloads | likes | lastModified | likes30d | trendingScore | mainSize | id | trending | upvotes\nTYPE values: file | dir | repo | bucket | collection | paper | link\nUse --kind mcp with search hf://spaces to filter for MCP Spaces. Repeat --tag only for space search.\nOmit --limit, --sort, and --type unless the request specifically requires them.",
    "inputSchema": {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "additionalProperties": false,
      "properties": {
        "operations": {
          "items": {
            "additionalProperties": false,
            "properties": {
              "args": {
                "description": "Command arguments; each array item is one grammar token.",
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              "cmd": {
                "description": "Command to execute.",
                "enum": [
                  "ls",
                  "cat",
                  "attach",
                  "stat",
                  "find",
                  "search"
                ],
                "type": "string"
              }
            },
            "required": [
              "cmd",
              "args"
            ],
            "type": "object"
          },
          "maxItems": 30,
          "minItems": 1,
          "type": "array"
        }
      },
      "required": [
        "operations"
      ],
      "type": "object"
    },
    "name": "hf:hf_fs"
  },
  {
    "description": "Retrieve detailed metadata about a file or directory — including size, creation time, last modified time, permissions, and type — without reading its content. Use read_text_file or read_media_file instead when you need the actual file content.\n\nParameters:\n- path: Path to the file or directory to inspect (must be within allowed directories)",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "properties": {
        "path": {
          "type": "string"
        }
      },
      "required": [
        "path"
      ],
      "type": "object"
    },
    "name": "fs:get_file_info"
  },
  {
    "description": "Reads file contents in various modes, returning text strings, base64 media blocks, or batched multi-file results.\nread_text: reads one file as a decoded text string; choose for plain text, source code, config files, etc.\nread_media: reads one file as base64 with MIME type detection; choose for images, audio, or binary files.\nread_multiple: reads several text files in one call; choose when you need more than one file to avoid repeated round-trips.\n\nAction parameters (\"?\" = optional):\n- read_text(path: string, tail?: number, head?: number)\n- read_media(path: string)\n- read_multiple(paths: array)",
    "inputSchema": {
      "properties": {
        "action": {
          "description": "Which operation to perform; see the tool description for each action.",
          "enum": [
            "read_text",
            "read_media",
            "read_multiple"
          ],
          "type": "string"
        },
        "arguments": {
          "description": "Arguments for the chosen action, matching its documented parameters.",
          "type": "object"
        }
      },
      "required": [
        "action",
        "arguments"
      ],
      "type": "object"
    },
    "name": "fs:file_reader"
  },
  {
    "description": "Scan provided file contents or diff hunks for exposed secrets such as API keys, tokens, passwords, and credentials. Returns detected secrets with locations and metadata. Accepts raw content strings, not file paths. Skip files listed in .gitignore. For full repository scanning, use other mechanisms.\n\nParameters:\n- files: Single string or array of strings containing raw file contents or diff hunks to scan (must not be empty)\n- owner: Repository owner (used for context)\n- repo: Repository name (used for context)",
    "inputSchema": {
      "properties": {
        "files": {
          "anyOf": [
            {
              "minLength": 1,
              "type": "string"
            },
            {
              "items": {
                "type": "string"
              },
              "maxItems": 100,
              "minItems": 1,
              "type": "array"
            }
          ],
          "description": "A single string or an array of strings containing file contents, snippets, or diff hunks to scan for secrets. These must be raw contents, not repository file paths."
        },
        "owner": {
          "description": "Repository owner",
          "type": "string",
          "x-mcp-header": "owner"
        },
        "repo": {
          "description": "Repository name",
          "type": "string",
          "x-mcp-header": "repo"
        }
      },
      "required": [
        "files",
        "owner",
        "repo"
      ],
      "type": "object"
    },
    "name": "github:run_secret_scanning"
  },
  {
    "description": "Covers reading and writing files in a GitHub repository; returns file content, directory listings, or commit confirmation.\nget_contents: Reads a file or lists a directory at a given ref or blob SHA. Use when content is needed without modification.\ncreate_or_update: Writes or overwrites a single file in a commit. Requires the current SHA when updating an existing file.\npush_multiple: Commits multiple files in a single push. Use instead of create_or_update when batching changes.\ndelete: Removes a file from a branch with a commit message. Use only when the file should be gone entirely.\n\nAction parameters (\"?\" = optional):\n- get_contents(fields?: array, owner: string, path?: string (default /), ref?: string, repo: string, sha?: string)\n- create_or_update(allow_symlink_write?: boolean (default false), branch: string, content: string, message: string, owner: string, path: string, repo: string, sha?: string)\n- push_multiple(branch: string, files: array, message: string, owner: string, repo: string)\n- delete(branch: string, message: string, owner: string, path: string, repo: string)",
    "inputSchema": {
      "properties": {
        "action": {
          "description": "Which operation to perform; see the tool description for each action.",
          "enum": [
            "get_contents",
            "create_or_update",
            "push_multiple",
            "delete"
          ],
          "type": "string"
        },
        "arguments": {
          "description": "Arguments for the chosen action, matching its documented parameters.",
          "type": "object"
        }
      },
      "required": [
        "action",
        "arguments"
      ],
      "type": "object"
    },
    "name": "github:file"
  },
  {
    "description": "DEPRECATED — use read_text_file instead. Read the complete contents of a file as text, with optional head/tail line limiting.\n\nParameters:\n- path: Path to the file to read (must be within allowed directories)\n- head: If set, return only the first N lines\n- tail: If set, return only the last N lines",
    "inputSchema": {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "properties": {
        "head": {
          "description": "If provided, returns only the first N lines of the file",
          "type": "number"
        },
        "path": {
          "type": "string"
        },
        "tail": {
          "description": "If provided, returns only the last N lines of the file",
          "type": "number"
        }
      },
      "required": [
        "path"
      ],
      "type": "object"
    },
    "name": "fs:read_file"
  }
]

